DO $$ 
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'distributionhubs' AND column_name = 'utilization_class') THEN
        ALTER TABLE distributionhubs ADD COLUMN utilization_class VARCHAR(30);
    END IF;
    UPDATE distributionhubs SET utilization_class = CASE WHEN ROUND(CAST((hubutilpct / 100.0) * (storecapm3::numeric / NULLIF(storeavailm3, 0)) AS numeric), 2) > 5 THEN 'High Utilization' WHEN ROUND(CAST((hubutilpct / 100.0) * (storecapm3::numeric / NULLIF(storeavailm3, 0)) AS numeric), 2) >= 2 THEN 'Moderate Utilization' ELSE 'Low Utilization' END;
END $$;

ALTER TABLE distributionhubs ADD CONSTRAINT check_valid_rur CHECK (storeavailm3 IS NOT NULL AND storecapm3 IS NOT NULL);

CREATE OR REPLACE FUNCTION maintain_utilization_class_func()
RETURNS TRIGGER AS $$
BEGIN
    NEW.utilization_class = CASE 
        WHEN ROUND(CAST((NEW.hubutilpct / 100.0) * (NEW.storecapm3::numeric / NULLIF(NEW.storeavailm3, 0)) AS numeric), 2) > 5 THEN 'High Utilization'
        WHEN ROUND(CAST((NEW.hubutilpct / 100.0) * (NEW.storecapm3::numeric / NULLIF(NEW.storeavailm3, 0)) AS numeric), 2) >= 2 THEN 'Moderate Utilization'
        ELSE 'Low Utilization'
    END;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS maintain_utilization_class ON distributionhubs;

CREATE TRIGGER maintain_utilization_class
BEFORE INSERT OR UPDATE ON distributionhubs
FOR EACH ROW
EXECUTE FUNCTION maintain_utilization_class_func();

